<#
.SYNOPSIS
  Upgrades your NOC Atlas or IT Atlas vault to the IT Atlas and updates the IT Atlas (Gesture Graph) plugin. No admin rights needed.

.DESCRIPTION
  1. Copies the whole vault to a timestamped backup folder first.
  2. Replaces the generated notes with the new versions and adds the new Help Desk notes.
     Text you wrote under "## Field notes" in a note is carried over into the new version.
  3. Removes old generated notes that were renamed (for example the old week names).
     Notes you created yourself are never touched.
  4. Keeps your Obsidian settings and plugins; refreshes the graph colours and bookmarks.
  5. Installs the new plugin version, keeping its settings and downloaded hand model.

.EXAMPLE
  powershell -ExecutionPolicy Bypass -File .\update-it-atlas.ps1
  powershell -ExecutionPolicy Bypass -File .\update-it-atlas.ps1 -Vault "C:\Users\me\Documents\NOC-Atlas"
#>
[CmdletBinding()]
param([string]$Vault = '')

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
function Step($m) { Write-Host ""; Write-Host "==> $m" -ForegroundColor Cyan }
function Ok($m)   { Write-Host "   [ok] $m" -ForegroundColor Green }
function Warn($m) { Write-Host "   [!]  $m" -ForegroundColor Yellow }
function Die($m)  { Write-Host "   [x]  $m" -ForegroundColor Red; exit 1 }
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$Stamp = Get-Date -Format 'yyyyMMdd-HHmmss'

if (-not $PSCommandPath) { Die "Run this as a saved .ps1 file (it reads its own embedded data)." }
$Docs = [Environment]::GetFolderPath('MyDocuments')
if (-not $Docs) { $Docs = Join-Path $HOME 'Documents' }
if (-not $Vault) {
    foreach ($v in @((Join-Path $Docs 'IT-Atlas'), (Join-Path $Docs 'NOC-Atlas'), (Join-Path $HOME 'NOC-Atlas'), (Join-Path $HOME 'IT-Atlas'))) {
        if (Test-Path -LiteralPath (Join-Path $v '.obsidian')) { $Vault = $v; break }
    }
}
if (-not $Vault) { Die "Couldn't find your atlas vault. Run with -Vault ""C:\path\to\NOC-Atlas""" }
$Vault = [IO.Path]::GetFullPath($Vault)
if (-not (Test-Path -LiteralPath (Join-Path $Vault '.obsidian'))) { Die "$Vault is not an Obsidian vault (no .obsidian folder)." }

if (Get-Process -Name 'Obsidian' -ErrorAction SilentlyContinue) {
    Warn "Obsidian is open. Close it first so it doesn't hold old copies of notes."
    $a = Read-Host "   Continue anyway? [y/N]"
    if ($a -notmatch '^[Yy]') { exit 1 }
}

# Work folder under LOCALAPPDATA (long path; TEMP can be an 8.3 short path that PS 5.1 mishandles).
$WorkRoot = Join-Path $env:LOCALAPPDATA ('it-brain-update-' + [guid]::NewGuid().ToString('N'))
[IO.Directory]::CreateDirectory($WorkRoot) | Out-Null

try {
    Step "Backing up $Vault"
    $Bak = "$Vault.backup-$Stamp"
    Copy-Item -LiteralPath $Vault -Destination $Bak -Recurse
    Ok "Backup at $Bak"

    Step "Unpacking the IT Atlas"
    $self = [IO.File]::ReadAllText($PSCommandPath)
    $tag = 'PAYLOAD'  # built from a variable so the pattern can't match this line itself
    $m = [regex]::Match($self, "(?s)<#${tag}_BEGIN\s*(.*?)\s*${tag}_END#>")
    if (-not $m.Success) { Die "Embedded data not found. Is the script complete?" }
    $zip = Join-Path $WorkRoot 'payload.zip'
    [IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String(($m.Groups[1].Value -replace '\s', '')))
    Expand-Archive -LiteralPath $zip -DestinationPath $WorkRoot -Force
    $New = Join-Path $WorkRoot 'IT-Atlas'; $Plug = Join-Path $WorkRoot 'gesture-graph'
    if (-not (Test-Path -LiteralPath $New) -or -not (Test-Path -LiteralPath $Plug)) { Die "Unpacked data is incomplete." }
    Ok "$(@(Get-ChildItem -LiteralPath $New -Recurse -File -Filter '*.md').Count) notes ready"

    # The user's own lines from a note's "## Field notes" section (empty if untouched).
    function Get-FieldNotes([string]$Path) {
        $lines = [IO.File]::ReadAllLines($Path); $in = $false; $out = @()
        foreach ($l in $lines) {
            if ($l -match '^## Field notes\s*$') { $in = $true; continue }
            if ($in -and $l -match '^## ') { $in = $false }
            if ($in -and $l.Trim() -and $l -notmatch '^Add your own tips') { $out += $l }
        }
        return $out
    }

    Step "Updating notes"
    $updated = 0; $added = 0; $kept = 0; $removed = 0
    $obsDir = Join-Path $New '.obsidian'
    foreach ($f in Get-ChildItem -LiteralPath $New -Recurse -File) {
        if ($f.FullName.StartsWith($obsDir + [IO.Path]::DirectorySeparatorChar)) { continue }
        $rel = $f.FullName.Substring($New.Length).TrimStart('\', '/')
        $dst = Join-Path $Vault $rel
        [IO.Directory]::CreateDirectory((Split-Path -Parent $dst)) | Out-Null
        if ((Test-Path -LiteralPath $dst) -and $rel.EndsWith('.md')) {
            # only lines the user added: drop anything the new version already has in that section
            $theirs = @(Get-FieldNotes $f.FullName)
            $mine = @(Get-FieldNotes $dst | Where-Object { $theirs -notcontains $_ })
            Copy-Item -LiteralPath $f.FullName -Destination $dst -Force
            if ($mine.Count) {
                $text = [IO.File]::ReadAllText($dst, $Utf8NoBom)
                if ($text -notmatch '(?m)^## Field notes') { $text += "`n## Field notes`n`n" }
                [IO.File]::WriteAllText($dst, $text + (($mine -join "`n") + "`n"), $Utf8NoBom)
                $kept++
            }
            $updated++
        } else {
            Copy-Item -LiteralPath $f.FullName -Destination $dst -Force
            if ($rel.EndsWith('.md')) { $added++ }
        }
    }
    foreach ($rel in [IO.File]::ReadAllLines((Join-Path $New '_system\generated-files.txt'))) {
        if (-not $rel.Trim()) { continue }
        $old = Join-Path $Vault ($rel -replace '/', '\')
        $nw = Join-Path $New ($rel -replace '/', '\')
        if ((Test-Path -LiteralPath $old) -and -not (Test-Path -LiteralPath $nw)) {
            if (@(Get-FieldNotes $old).Count) { Warn "Kept $rel (it has your Field notes; it was renamed in this version)"; continue }
            [IO.File]::Delete($old); $removed++
        }
    }
    Ok "$updated notes updated, $added new, $removed old ones removed"
    if ($kept) { Ok "Carried over your Field notes in $kept note(s)" }

    Step "Refreshing Obsidian settings"
    foreach ($c in 'graph.json', 'bookmarks.json', 'templates.json') {
        Copy-Item -LiteralPath (Join-Path $obsDir $c) -Destination (Join-Path $Vault ".obsidian\$c") -Force
    }
    Ok "Graph colours (including the new Help Desk colour) and bookmarks updated; your plugins and other settings are untouched"

    Step "Updating the IT Atlas plugin"
    $targets = @($Vault)
    foreach ($w in @((Join-Path $Docs 'Rehan-Vault'), (Join-Path $HOME 'Rehan-Vault'))) {
        if (Test-Path -LiteralPath (Join-Path $w '.obsidian\plugins\gesture-graph')) { $targets += $w }
    }
    foreach ($t in $targets) {
        $P = Join-Path $t '.obsidian\plugins\gesture-graph'
        [IO.Directory]::CreateDirectory($P) | Out-Null
        Copy-Item -Path (Join-Path $Plug '*') -Destination $P -Recurse -Force
        $cp = Join-Path $t '.obsidian\community-plugins.json'
        $list = @()
        if (Test-Path -LiteralPath $cp) { try { $list = @((Get-Content -LiteralPath $cp -Raw | ConvertFrom-Json) | ForEach-Object { $_ }) } catch { $list = @() } }
        if ($list -notcontains 'gesture-graph') { $list += 'gesture-graph' }
        [IO.File]::WriteAllText($cp, '[' + (($list | ForEach-Object { "`n  `"$_`"" }) -join ',') + "`n]`n", $Utf8NoBom)
        Ok "Plugin installed and enabled in $t"
    }

    Step "Done"
    Write-Host "   Vault:   $Vault  (backup: $Bak)"
    Write-Host "   Open Obsidian, then click the brain icon in the left ribbon for the IT Atlas."
    Write-Host "   New:     828 pages: 76 everyday fixes, 348 tools, 133 concepts, 48 playbooks,"
    Write-Host "            Junior/Mid/Senior levels, career tracks and two new lobes (DevOps, Compliance)."
    Write-Host "   If something looks wrong, the backup folder above is a complete copy of your old vault."
} finally {
    try { [IO.Directory]::Delete($WorkRoot, $true) } catch { }
}

